import os
import pwd
import re
import shutil
import stat
import tomllib
from pathlib import Path


class LoginPreflight:
    """Read-only snapshot and conservative validation of the supported login template."""

    FILES = ('hyprland-greet.conf', 'regreet.toml', 'regreet.css')
    LIMIT = 65536
    CONFIG = '[terminal]\nvt = 1\n\n[default_session]\ncommand = "Hyprland --config /etc/greetd/hyprland-greet.conf"\nuser = "greeter"\n'
    HYPR_KEYS = {
        '': {'autogenerated'},
        'input': {'kb_layout', 'kb_variant', 'kb_options'},
        'ecosystem': {'no_update_news'},
        'misc': {'disable_hyprland_logo', 'disable_splash_rendering', 'force_default_wallpaper'},
        'animations': {'enabled'},
        'binds': {'pass_mouse_when_bound'},
    }
    EXEC = {'regreet', "sh -c 'regreet; hyprctl dispatch exit'",
            "sh -c 'sleep 0.5 && hyprctl dismissnotify -1'"}

    def __init__(self, env, root=Path('/'), which=shutil.which, greeter_lookup=pwd.getpwnam):
        self.env, self.root, self.which, self.greeter_lookup = env, Path(root), which, greeter_lookup

    @staticmethod
    def regular_bytes(path):
        limit = 64 * 1024 * 1024 if path.name == "regreet-background.jpg" else LoginPreflight.LIMIT
        info = path.lstat()
        if not stat.S_ISREG(info.st_mode):
            raise ValueError(f'Expected a regular login file: {path}')
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, 'rb') as stream:
            opened = os.fstat(stream.fileno())
            if not stat.S_ISREG(opened.st_mode) or (info.st_dev, info.st_ino) != (opened.st_dev, opened.st_ino):
                raise ValueError(f'Login file changed while opening: {path}')
            data = stream.read(limit + 1)
            if len(data) > limit:
                raise ValueError(f'Login file exceeds safe snapshot size: {path}')
            after = os.fstat(stream.fileno())
            if ((opened.st_size, opened.st_mtime_ns, opened.st_ctime_ns) !=
                    (after.st_size, after.st_mtime_ns, after.st_ctime_ns)):
                raise ValueError(f'Login file changed while reading: {path}')
        return data

    @staticmethod
    def fingerprint(path):
        info = path.stat()
        return info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns, info.st_ctime_ns

    def read_source(self, path):
        resolved = path.resolve(strict=True)
        roots = (self.env.home_dir.resolve(), self.env.dotfiles_dir.resolve())
        if not any(resolved.is_relative_to(root) for root in roots):
            raise ValueError(f'Login source points outside the managed HOME/checkout: {path}')
        return self.regular_bytes(resolved).decode('utf-8')

    @staticmethod
    def check_display_manager(root):
        path = root / 'etc/systemd/system/display-manager.service'
        if path.is_symlink():
            # The alias is the display-manager selection, including a stale alias.
            if Path(os.readlink(path)).name != 'greetd.service':
                raise ValueError(f'Conflicting display manager: {path} -> {os.readlink(path)}; change it manually from a TTY')
        elif path.exists():
            raise ValueError(f'Unknown display manager configuration: {path}; inspect it manually')

    @staticmethod
    def validate_hypr(content):
        block = ''
        launched = False
        for raw in content.splitlines():
            line = raw.strip()
            if not line or line.startswith('#'):
                continue
            if line.endswith('{'):
                name = line[:-1].strip()
                if block or name not in LoginPreflight.HYPR_KEYS or not name:
                    raise ValueError('Unsupported Hyprland login block; use the shipped minimal login template')
                block = name
            elif line == '}':
                if not block:
                    raise ValueError('Unbalanced Hyprland login configuration')
                block = ''
            elif '=' in line:
                key, value = (item.strip() for item in line.split('=', 1))
                if not block and key == 'exec-once' and value in LoginPreflight.EXEC:
                    launched = launched or 'regreet' in value
                elif key not in LoginPreflight.HYPR_KEYS[block] or not re.fullmatch(r'[A-Za-z0-9_,:+. -]*', value):
                    raise ValueError('Unsupported Hyprland login directive; use the shipped minimal login template')
                elif block not in {'input'}:
                    allowed = {'0', '1'} if key == 'autogenerated' else {'0', '1', '2', '-1'} if key == 'force_default_wallpaper' else {'true', 'false'}
                    if value not in allowed:
                        raise ValueError('Invalid Hyprland login setting value')
            else:
                raise ValueError('Invalid Hyprland login configuration')
        if block or not launched:
            raise ValueError('Hyprland login configuration must launch regreet and have balanced blocks')

    @staticmethod
    def validate_css(content):
        if re.search(r'@import\b|url\s*\(', content, flags=re.I):
            raise ValueError('Login CSS external resources/imports require manual validation')
        without_comments = re.sub(r'/\*.*?\*/', '', content, flags=re.S)
        without_strings = re.sub(r'"(?:\\.|[^"\\])*"|\x27(?:\\.|[^\x27\\])*\x27', '', without_comments)
        stack = []
        for token in re.findall(r'[{}()]', without_strings):
            if token in '{(':
                stack.append(token)
            elif not stack or stack.pop() != {'}': '{', ')': '('}[token]:
                raise ValueError('Unbalanced login CSS')
        if stack or not content.strip():
            raise ValueError('Empty/unbalanced login CSS')

    @staticmethod
    def validate_files(files):
        for name, content in files.items():
            if not isinstance(content, str) or not content.strip() or '\x00' in content:
                raise ValueError(f'Empty/invalid login input: {name}')
            if name == 'hyprland-greet.conf':
                LoginPreflight.validate_hypr(content)
            elif name == 'regreet.css':
                LoginPreflight.validate_css(content)
            elif name == 'regreet.toml':
                settings = tomllib.loads(content)
                if set(settings) - {'background', 'GTK', 'appearance'}:
                    raise ValueError('Unknown ReGreet settings require manual validation')
                background = settings.get('background', {})
                if not isinstance(background, dict):
                    raise ValueError('Invalid ReGreet background settings')
                if background and background.get('path') != '/etc/greetd/regreet-background.jpg':
                    raise ValueError('Unsupported login background; regenerate configuration for the resource-free fallback')
                if not isinstance(settings.get('GTK', {}), dict):
                    raise ValueError('Invalid ReGreet GTK settings')
            elif name == 'config.toml':
                settings = tomllib.loads(content)
                session = settings.get('default_session', {})
                allowed = {'Hyprland --config /etc/greetd/hyprland-greet.conf',
                           'Hyprland --config /etc/greetd/hyprland-greet.conf > /dev/null 2>&1'}
                if session.get('user') != 'greeter' or session.get('command') not in allowed:
                    raise ValueError('Unknown greetd session; inspect custom configuration manually')

    @staticmethod
    def fallback(content):
        settings = tomllib.loads(content)
        if 'background' not in settings:
            return content
        if settings['background'].get('path') != '/etc/greetd/regreet-background.jpg':
            raise ValueError('Unsupported login background resource; regenerate with dotfiles configure')
        # Retire the historical, potentially absent image dependency. Keep all other tables.
        return re.sub(r'(?ms)^\[background\]\s*\n.*?(?=^\[|\Z)', '', content)

    def build(self, permissions_only=False):
        payload = {'version': 1, 'permissions_only': permissions_only,
                   'user': self.env.user, 'home': str(self.env.home_dir), 'files': {}}
        if permissions_only:
            return payload
        self.check_display_manager(self.root)
        source = self.env.home_dir / '.config/greetd'
        paths = [source / name for name in self.FILES]
        before = {path: self.fingerprint(path) for path in paths}
        files = {path.name: self.read_source(path) for path in paths}
        if any(self.fingerprint(path) != before[path] for path in paths):
            raise ValueError('Login inputs changed during snapshot; retry after configure completes')
        files['regreet.toml'] = self.fallback(files['regreet.toml'])
        files['config.toml'] = self.CONFIG
        self.validate_files(files)
        if sum(len(value.encode()) for value in files.values()) > self.LIMIT:
            raise ValueError('Login snapshot exceeds safe size')
        for binary in ('Hyprland', 'regreet', 'hyprctl', 'greetd', 'python3', 'visudo'):
            found = self.which(binary)
            if not found:
                raise ValueError(f'Missing login binary: {binary}')
            executable = Path(found)
            if (not executable.is_absolute() or not executable.is_file() or not os.access(executable, os.X_OK)
                    or executable.stat().st_mode & 0o022 or executable.stat().st_uid != 0):
                raise ValueError(f'Unsafe login binary: {binary} ({found})')
        try:
            account = self.greeter_lookup('greeter')
            if getattr(account, 'pw_uid', 0) <= 0:
                raise ValueError('The greeter account must be an unprivileged system user')
        except KeyError as error:
            raise ValueError('Missing greeter account; install and inspect greetd first') from error
        payload['files'] = files
        return payload
